mapper.select:
        	SELECT
		ROUND(SUM( IFNULL(info.medical_history_money,0) + IFNULL(info.troubleshooting_money,0)
	 + IFNULL(info.printing_money,0) + IFNULL(info.accommodatio_money,0) + IFNULL(info.train_money,0) + IFNULL(info.car_money,0) + IFNULL(info.aircraft_money,0) + IFNULL(info.self_driving_money,0) + IFNULL(info.other_money,0) + IFNULL(info.innercity_money,0)+ IFNULL(info.toll_money,0)),2) totalMoney
			FROM survey_case_direction direction LEFT JOIN survey_reimbursement_info info ON direction.id = survey_direction_id
				WHERE direction.survey_info_id = #{surveyInfoId} AND direction.delete_flag = 0 AND direction.survey_investigator_case_id =#{investigatorCaseId}
				AND direction.have_reimbursement = 1 AND info.survey_user_id = #{currentUserId}

    SELECT ROUND(SUM( IFNULL(medical_history_money,0) + IFNULL(troubleshooting_money,0)
	 + IFNULL(printing_money,0) + IFNULL(accommodatio_money,0) + IFNULL(train_money,0) + IFNULL(car_money,0) + IFNULL(aircraft_money,0) + IFNULL(self_driving_money,0) + IFNULL(other_money,0)+ IFNULL(innercity_money,0) + IFNULL(toll_money,0) ),2) totalMoney
        FROM survey_reimbursement_info WHERE survey_direction_id = #{dicectionId}

SELECT SUM( ifnull( c.medical_history_money, 0 )) medicalHistoryMoney, SUM( ifnull( c.accommodatio_money, 0 ) ) accommodatioMoney, sum( ifnull( c.troubleshooting_money, 0 ) ) troubleshootingMoney, sum( ifnull( c.opc_troubleshooting_money, 0 ) ) opcTroubleshootingMoney, SUM( ifnull( c.printing_money, 0 ) ) printingMoney, sum( IFNULL(c.cross_driving_money, 0 ) + ifnull(c.self_driving_money,0)+ ifnull(c.toll_money,0) ) crossCityTransportationFees, SUM( ifnull( c.other_money, 0 )) otherFee, sum(ifnull(c.cityin_driving_money,0)) cityTransportationSubsidies FROM survey_user_clock u LEFT JOIN survey_clock_case c ON u.id = c.clock_id LEFT JOIN survey_investigator i ON u.survey_user_id = i.user_id WHERE date_format(u.clock_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d') and date_format(u.clock_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d') AND u.survey_org_id = #{orgId}
AND i.survey_area_id = #{areaId}
AND i.survey_area_id is null
AND c.entrust_type = 2
AND c.entrust_type = 1
